    socialPanel?.render({ covered: townTalk.hudCovered || (modes?.hudCovered ?? false) || gamePaused() });
    profileWin?.render({ covered: townTalk.hudCovered || (modes?.hudCovered ?? false) || gamePaused() });   // INSPECT1: the F-menu's own covering word
