    // WB3b: the court's climate and region - its gate's pixel's (the omen's site, when it is that day's)
    gateArenaSite: (g) => {
      const ci = maps.getClimateIndex(g.px, g.py);
      const climateType = getWorldClimateSettings(ci).climateType;
      const site = gateOmen?.current?.()?.site;
      const mine = site?.day === g.day;
      return { climateBase: climateType, season: INTERIOR_SEASON, climate: { worldClimate: ci, climateType }, regionIndex: mine ? site.region : -1, regionName: mine ? site.regionName : '' };
    },
    gateLanding: (g) => gateLandingFor(g, { pixelTranslation: (px, py) => state.pixelTranslation(px, py), heightAt: (x, z) => heightAt(x, z) }),   // WB3b: the way home, before the gate
    dungeonStartSite: () => {
      const p = playerTravelPixel();
      const key = `${p.x},${p.y}`;
      const dfLocation = locationIndex.get(key) ?? null;
      if (!dfLocation?.hasDungeon) return null;
      return { dfLocation, climateBase: getWorldClimateSettings(maps.getClimateIndex(p.x, p.y)).climateType, season: INTERIOR_SEASON, group: key, door: null, dfBlock: null, recordIndex: -1 };
    },
    // WORLD-HOVER: the token that says whether the list above is still
    // the one it was. See `doorGeneration`'s own note for why this
    // host has one and the fixed city does not.
    doorGeneration: () => doorGeneration,
    // IS1: the save composer's doors for the interior mode's pause and
    // F9/F11 (GameManager.cs:570-586 dispatches the quick keys
    // scene-free). THE FOUR HOSTS: world.js hands its ONE composer in
    // here and worldModes' interior arm consumes it;
    // dungeonContext.js keeps its own composer (no buildings there);
