    loadKey: (key) => worldQuickLoad({ key }),
    // AUDIT 26 (F019): RMBLayout's exterior StaticNPCs, shifted through
    // the LIVE floating-origin translation exactly as shiftedDoor does
    // - the activation ray works in world space
    // (PlayerActivate.ActivateStaticNPC :741-767).
    npcTargets: () => {
      const out = [];
      for (const p of built.values()) {
        if (!p.npcs?.length) continue;
        const t = state.pixelTranslation(p.px, p.py);
        // E3: a person the quest machine's away arm deactivated is not
        // a target - SetActive(false) takes the BoxCollider with the
        // billboard, so DFU's ray meets nothing there either.
        for (const pn of p.npcs) {
          if (!pn.active) continue;
          out.push({ ...pn, x: pn.x + t[0], y: pn.y + t[1], z: pn.z + t[2] });
        }
      }
      return out;
    },
    // THE BULLETIN BOARDS, through the same LIVE floating-origin
    // translation the street NPCs ride - DFU's own hit is a world-space
    // raycast (PlayerActivate.cs:314, :393-398), so the box has to be
    // in the frame the ray is cast in. pickActivatable takes
    // {min,max}; the pixel keeps the 6-array the culling box uses.
    boardTargets: () => {
      const out = [];
      for (const p of built.values()) {
        if (!p.boards?.length) continue;
        const t = state.pixelTranslation(p.px, p.py);
        for (const b of p.boards) {
          out.push({
            min: [b.box[0] + t[0], b.box[1] + t[1], b.box[2] + t[2]],
            max: [b.box[3] + t[0], b.box[4] + t[1], b.box[5] + t[2]],
          });
        }
      }
      return out;
    },
    /** AUDIT 64 F11: the StaticBuildings of every built pixel, shifted
     *  through the LIVE floating-origin translation the boards and
     *  street NPCs ride - DFU's hit test consumes a world-space
     *  raycast's point (PlayerActivate.cs:314, :343). The pixel key and
     *  the pixel-local matrix ride along, because the identity lookup
     *  (buildingDataForDoor) works in the pixel's own location frame. */
    buildingTargets: () => {
      const out = [];
      for (const p of built.values()) {
        if (!p.buildings?.length) continue;
        const t = state.pixelTranslation(p.px, p.py);
        for (const bl of p.buildings) {
          out.push({
            ...bl, pixelKey: `${p.px},${p.py}`,
            aabb: {
              min: [bl.aabb.min[0] + t[0], bl.aabb.min[1] + t[1], bl.aabb.min[2] + t[2]],
              max: [bl.aabb.max[0] + t[0], bl.aabb.max[1] + t[1], bl.aabb.max[2] + t[2]],
            },
          });
        }
      }
      return out;
    },
